def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    opp_defections = 0
    my_defections = 0
    for m, o in history:
        if o == 'D':
            opp_defections += 1
        if m == 'D':
            my_defections += 1
    if opp_defections > n * 0.5:
        return 'D'
    if opp_defections == 0 and my_defections < 3:
        return 'D'
    return 'C'
